@case('意外异常中文响应', '隔离应用注入未预期的运行异常并发起注册。', '模拟内部异常', '返回中文JSON错误，日志保留traceback；不向用户返回英文或内部细节。')
def test_unexpected_error_message(client,monkeypatch,caplog):
    from app import auth
    def broken(*args): raise RuntimeError('internal diagnostic only')
    monkeypatch.setattr(auth,'digest',broken)
    probe=TestClient(client.app,raise_server_exceptions=False)
    try:
        with caplog.at_level(logging.ERROR):
            r=probe.post('/api/auth/register',json={'username':'new_user','password':'password123'})
        assert r.status_code==500 and '服务暂时' in r.json()['detail']
        assert 'internal' not in r.text and any(record.exc_info for record in caplog.records)
    finally: probe.close()

@case('注册唯一性', '首次注册，再同名及大小写变体注册；检查用户数。', 'same_user、SAME_USER', '201、409、409；只有一条用户；唯一索引存在。')
def test_register_duplicate(client):
    assert client.post('/api/auth/register', json=BODY).status_code == 201
    for name in ('same_user', 'SAME_USER'):
        r = client.post('/api/auth/register', json={**BODY, 'username': name})
        assert r.status_code == 409 and r.json()['detail'] == '用户名已存在'
    assert client.app.state.db.users.count_documents({}) == 1
    assert username_index_ready(client.app.state.db)

@case('缺失索引修复', '在隔离库移除索引后注册；重复请求；检查索引。', '空用户集合、缺失索引', '注册前重建唯一索引，201后409。')
def test_missing_index_rebuilt(client):
    client.app.state.db.users.drop_index('username_1')
    assert client.post('/api/auth/register', json=BODY).status_code == 201
    assert username_index_ready(client.app.state.db)
    assert client.post('/api/auth/register', json=BODY).status_code == 409

@case('注册密码长度', '用指定长度注册；核对响应与用户数；合法密码再次登录。', '7、8、16、17、128字符及8/16/17个Unicode字符', '仅8～16字符可注册，非法请求422且不写入；合法账号可登录。')
@pytest.mark.parametrize('password,expected', [('a'*7,422),('a'*8,201),('a'*16,201),('a'*17,422),('a'*128,422),('😀'*8,201),('😀'*16,201),('😀'*17,422)])
def test_registration_password_bounds(client,password,expected):
    body={'username':'policy_user','password':password}
    assert client.post('/api/auth/register',json=body).status_code==expected
    assert client.app.state.db.users.count_documents({})==(1 if expected==201 else 0)
    if expected==201:
        assert client.post('/api/auth/login',json=body).status_code==200

